confirm.expr:
#('Restarting {0} also restarts the services depending on it:
{1}

Restart them all?'@en, 'Beim Neustart von {0} werden auch die davon abhängigen Dienste neu gestartet:
{1}

Alle neu starten?'@de).fill(serviceLabel($module), serviceDependents($module))

start-job.function:
{
	$job.jobIndeterminate();
	$job.jobMessage(#('Rebuilding the full-text index.'@en, 'Der Volltextindex wird neu aufgebaut.'@de));
	indexingRebuild();
	#('The full-text index has been rebuilt.'@en, 'Der Volltextindex wurde neu aufgebaut.'@de);
}

{
	$job.jobIndeterminate();
	$job.jobMessage(#('Rebuilding the security storage.'@en, 'Der Sicherheitsspeicher wird neu aufgebaut.'@de));
	securityStorageRebuild();
	#('The security storage has been rebuilt.'@en, 'Der Sicherheitsspeicher wurde neu aufgebaut.'@de);
}
